	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error describes one validation failure.
type Error struct {
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Result aggregates the errors found while validating a document.
type Result struct {
	Errors []Error `json:"errors"`
}

// FeaturesValidator holds the compiled feature schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

// NewFeaturesValidator compiles the embedded schema.
func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, fmt.Errorf("compile feature schema: %w", err)
	}
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks a YAML document and returns every validation error.
func (v *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	f, err := yaml.Extract(file, b)
	if err != nil {
		return resultForError(file, err), ErrValidationFailed
	}

	yv := v.v.Unify(v.cue.BuildFile(f, cue.Scope(v.v)))
	if err := yv.Validate(); err != nil {
		return resultForError(file, err), ErrValidationFailed
	}
	return Result{Errors: []Error{}}, nil
}

func resultForError(file string, err error) Result {
	result := Result{Errors: []Error{}}
	for _, issue := range cueerror.Errors(err) {
		format, args := issue.Msg()
		position := sourcePosition(file, issue)
		result.Errors = append(result.Errors, Error{
			Path:     strings.Join(issue.Path(), "."),
			Message:  fmt.Sprintf(format, args...),
			Location: Location{File: file, Line: position.Line(), Column: position.Column()},
		})
	}
	if len(result.Errors) == 0 {
		result.Errors = append(result.Errors, Error{Message: err.Error(), Location: Location{File: file}})
	}
	return result
}

// CUE may list schema positions before the source position. Select the
// position from the YAML file so each error points to its own field.
func sourcePosition(file string, issue cueerror.Error) token.Pos {
	for _, position := range issue.InputPositions() {
		if position.IsValid() && position.Filename() == file {
			return position
		}
	}
	if position := issue.Position(); position.IsValid() && position.Filename() == file {
		return position
	}
	return token.NoPos
}

// ValidateBytes validates YAML against the feature schema.
func ValidateBytes(b []byte) error {
	v, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	_, err = v.Validate("", b)
	return err
}

func writeErrorDetails(format string, result Result, w io.Writer) error {
	if format == jsonFormat {
		return json.NewEncoder(w).Encode(result)
	}
	if format != textFormat {
		if _, err := fmt.Fprintln(w, "Invalid format chosen, defaulting to '"\\\"text\\\" format...\"); err "'!= nil {
			return err
		}
	}
	if _, err := fmt.Fprintln(w, "❌ Validation failure!"); err != nil {
		return err
	}
	for _, issue := range result.Errors {
		if _, err := fmt.Fprintf(w, "'"\\n- %s: %s\\n  File   : %s\\n  Line   : %d\\n  Column : %d\\n\", issue.Path, issue.Message, issue.Location.File, issue.Location.Line, issue.Location.Column); err "'!= nil {
			return err
		}
	}
	return nil
}

// ValidateFiles validates all named files and writes the requested output.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	v, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	all := Result{Errors: []Error{}}
	for _, file := range files {
		b, err := os.ReadFile(file)
		if err != nil {
			return fmt.Errorf("read %s: %w", file, err)
		}
		result, err := v.Validate(file, b)
		if err != nil && !errors.Is(err, ErrValidationFailed) {
			return err
		}
		all.Errors = append(all.Errors, result.Errors...)
	}
	if len(all.Errors) > 0 {
		if err := writeErrorDetails(format, all, dst); err != nil {
			return err
		}
		return ErrValidationFailed
	}
	if format == jsonFormat {
		return json.NewEncoder(dst).Encode(all)
	}
	if format != textFormat {
		if _, err := fmt.Fprintln(dst, "Invalid format chosen, defaulting to '"\\\"text\\\" format...\"); err "'!= nil {
			return err
		}
	}
	_, err = fmt.Fprintln(dst, "✅ Validation success!")
	return err
}
